import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"قانون ضمان الإسكان","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0045-住房保障法.md","filePath":"ar/0045-住房保障法.md"}'),i={name:"ar/0045-住房保障法.md"};function e(o,t,n,h,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="قانون-ضمان-الإسكان" tabindex="-1">قانون ضمان الإسكان <a class="header-anchor" href="#قانون-ضمان-الإسكان" aria-label="Permalink to &quot;قانون ضمان الإسكان&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>45</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>حق السكن، المساكن المضمونة، المبادئ القانونية المكانية، البيئة الصالحة للسكن، مناهضة المضاربة</td></tr></tbody></table><h2 id="أولاً-الغرض-التشريعي-والمبادئ-الأساسية" tabindex="-1">أولاً: الغرض التشريعي والمبادئ الأساسية <a class="header-anchor" href="#أولاً-الغرض-التشريعي-والمبادئ-الأساسية" aria-label="Permalink to &quot;أولاً: الغرض التشريعي والمبادئ الأساسية&quot;">​</a></h2><p><em>قانون ضمان الإسكان</em> أحد القوانين الخمسة المساندة لحضارة التكافل المرساة. يهدف إلى ضمان حق السكن لجميع الكائنات داخل كون هنغ يوان، وإنشاء نظام ضمان إسكان عادل ومستدام، واستخدام تقنية تسيير المبادئ القانونية المكانية لتوفير مساحات سكنية ملائمة لعشرة آلاف عرق، ومنع المضاربة والافتراس في قطاع الإسكان.</p><p>يحدد هذا القانون المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>مبدأ ضمان السكن</td><td>لكل كائن الحق في الحصول على مساحة سكنية ملائمة؛ وعلى الدولة والحضارة واجب ضمان الاحتياجات السكنية الأساسية</td></tr><tr><td>أولوية المصلحة العامة</td><td>السكن أولاً ضرورة معيشية لا سلعة مضاربة؛ والمساكن المضمونة ذات خاصية المصلحة العامة</td></tr><tr><td>الكفاءة المكانية</td><td>استخدام تقنية تسيير المبادئ القانونية المكانية لرفع كفاءة استخدام المساحة وتوسيع المساحات الصالحة للسكن</td></tr><tr><td>التكيف مع الأعراق الأخرى</td><td>توفير مساحات سكنية ملائمة للخصائص الفسيولوجية وعادات المعيشة للأعراق المختلفة</td></tr><tr><td>البيئة الصالحة للسكن</td><td>يجب أن تتوفر في المساحات السكنية بيئة إيكولوجية جيدة وبنية تحتية وخدمات عامة</td></tr><tr><td>مناهضة المضاربة</td><td>حظر المضاربة بالسكن كهدف، ومنع تحول السكن إلى أداة لنهب الثروات</td></tr></tbody></table><h2 id="ثانياً-الضمانات-القانونية-لحق-السكن" tabindex="-1">ثانياً: الضمانات القانونية لحق السكن <a class="header-anchor" href="#ثانياً-الضمانات-القانونية-لحق-السكن" aria-label="Permalink to &quot;ثانياً: الضمانات القانونية لحق السكن&quot;">​</a></h2><p>ينص هذا القانون صراحةً على أن حق السكن حق أساسي يمنحه الدستور التكافلي لكل كائن، ويشمل على وجه التحديد:</p><ol><li><strong>الحق الأساسي في السكن</strong>: لكل كائن الحق في الحصول على مساحة سكنية لا تقل عن الحد الأدنى للمعيار، ويحدد الحد الأدنى وفق حجم جسد العرق واحتياجاته المعيشية.</li><li><strong>حق التقدم بطلب المساكن المضمونة</strong>: للكائنات المستوفية للشروط الحق في التقدم بطلب المساكن المضمونة، وتكون شروط الطلب ومعايير التوزيع علنية وشفافة.</li><li><strong>حق سلامة السكن</strong>: يجب أن تستوفي المساحات السكنية معايير السلامة؛ ولا يجوز تأجير أو توزيع المباني المتهالكة والمساحات غير الصالحة للسكن.</li><li><strong>حق استقرار السكن</strong>: يتمتع سكان المساكن المضمونة بحق سكن مستقر عند استيفاء الشروط، ولا يجوز طردهم تعسفاً.</li><li><strong>حق البيئة المعيشية</strong>: للساكن الحق في الحصول على هواء ومياه نظيفة وبيئة محيطة جيدة، والحق في تقديم شكاوى بشأن التلوث البيئي.</li><li><strong>حق تحسين السكن</strong>: للساكن الحق في تحسين مساحته السكنية بشكل معقول بشرط عدم التأثير على سلامة المبنى وحقوق الآخرين.</li></ol><h2 id="ثالثاً-نظام-ضمان-الإسكان" tabindex="-1">ثالثاً: نظام ضمان الإسكان <a class="header-anchor" href="#ثالثاً-نظام-ضمان-الإسكان" aria-label="Permalink to &quot;ثالثاً: نظام ضمان الإسكان&quot;">​</a></h2><p>ينقسم نظام ضمان الإسكان في حضارة التكافل المرساة إلى ثلاثة أنواع من المساكن، تغطي مستويات احتياج مختلفة:</p><table tabindex="0"><thead><tr><th>النوع</th><th>الاسم</th><th>الفئة المضمونة</th><th>طريقة التوزيع</th><th>الإيجار/السعر</th></tr></thead><tbody><tr><td>النوع الأول</td><td>المساكن العامة المؤجرة</td><td>الفئات منخفضة الدخل، المزارعون المبتدئون، المهاجرون الجدد</td><td>نظام الطلب والمراجعة، توزيع بالانتظار</td><td>إيجار منخفض رمزي</td></tr><tr><td>النوع الثاني</td><td>مساكن الملكية المشتركة</td><td>الفئات متوسطة الدخل، المزارعون المتوسطون</td><td>نظام الطلب والمراجعة، توزيع بالقرعة</td><td>أقل من سعر السوق، ملكية مشتركة بين الفرد والدولة</td></tr><tr><td>النوع الثالث</td><td>المساكن التجارية</td><td>الفئات مرتفعة الدخل، المزارعون المتقدمون</td><td>معاملة سوقية</td><td>سعر السوق، خاضع لقيود التنظيم</td></tr></tbody></table><p>بالإضافة إلى ذلك، تُستخدم تقنية تسيير المبادئ القانونية المكانية لبناء «مناطق سكنية ذات فضاء مطوي»: توسيع المساحة السكنية في الفضاء المادي المحدود عبر تقنية طي الفضاء، لتوفير مساحات سكنية أكبر للمناطق عالية الكثافة. يجب أن تخضع مناطق الفضاء المطوي لتقييم السلامة لضمان استقرار الفضاء.</p><h2 id="رابعاً-تكييف-المساكن-للأعراق-الأخرى" tabindex="-1">رابعاً: تكييف المساكن للأعراق الأخرى <a class="header-anchor" href="#رابعاً-تكييف-المساكن-للأعراق-الأخرى" aria-label="Permalink to &quot;رابعاً: تكييف المساكن للأعراق الأخرى&quot;">​</a></h2><p>مراعاةً للاحتياجات السكنية الخاصة للأعراق المختلفة داخل كون هنغ يوان، ينشئ هذا القانون نظام تكييف المساكن للأعراق الأخرى:</p><ul><li><strong>الأعراق المائية</strong>: توفير مساحات سكنية تحت الماء أو مساكن برمائية، مجهزة بأنظمة دوران المياه والحفاظ على جودتها.</li><li><strong>الأعراق الطائرة</strong>: توفير مساحات سكنية مرتفعة أو مساكن ذات منصات إقلاع وهبوط، مجهزة بإدارة الحركة الجوية.</li><li><strong>الكائنات الطاقية</strong>: توفير مساحات سكنية بتركيز طاقي مناسب، مجهزة بأجهزة تثبيت الطاقة.</li><li><strong>الأعراق العملاقة</strong>: توفير مساحات سكنية واسعة النطاق، مع تعزيز خاص للهياكل الإنشائية.</li><li><strong>الأعراق المتناهية الصغر</strong>: توفير مناطق سكنية متناهية الصغر، مجهزة بممرات مقياسية ومرافق خاصة.</li></ul><p>تُحدد معايير تكييف المساكن للأعراق الأخرى بالاشتراك بين الجهة المختصة بالإسكان وممثلي الأعراق المختلفة، وتُحدث دورياً.</p><h2 id="خامساً-بناء-المساكن-وإدارتها" tabindex="-1">خامساً: بناء المساكن وإدارتها <a class="header-anchor" href="#خامساً-بناء-المساكن-وإدارتها" aria-label="Permalink to &quot;خامساً: بناء المساكن وإدارتها&quot;">​</a></h2><ul><li><strong>تخطيط بناء المساكن</strong>: تضع الدولة خطط بناء المساكن وفقاً للنمو السكاني والهجرة، لضمان التوازن بين العرض والطلب على المساكن.</li><li><strong>معايير البناء</strong>: يجب أن يتوافق بناء المساكن المضمونة مع معايير السلامة وحماية البيئة والصلاحية للسكن؛ ويُحظر خفض جودة البناء.</li><li><strong>إدارة العقارات</strong>: تطبق المناطق السكنية نموذجاً يجمع بين الإدارة الذاتية والخدمات العقارية المهنية؛ وللساكنين الحق في المشاركة في قرارات إدارة العقارات.</li><li><strong>صيانة المساكن</strong>: تتولى جهة إدارة المساكن صيانة المساكن المضمونة، وتُخصص أموال الصيانة من التراكم العام.</li><li><strong>آلية الخروج</strong>: سكان المساكن المضمونة الذين يتجاوز دخلهم أو زراعتهم معيار الضمان يجب أن يخرجوا من المساكن المضمونة أو يتحولوا إلى المساكن التجارية، مع منح فترة انتقالية معقولة للخروج.</li></ul><h2 id="سادساً-مناهضة-المضاربة-والرقابة" tabindex="-1">سادساً: مناهضة المضاربة والرقابة <a class="header-anchor" href="#سادساً-مناهضة-المضاربة-والرقابة" aria-label="Permalink to &quot;سادساً: مناهضة المضاربة والرقابة&quot;">​</a></h2><p>لمنع المضاربة والافتراس في قطاع الإسكان، ينشئ هذا القانون تدابير الرقابة التالية:</p><ol><li>الحد من عدد المساكن التجارية التي يملكها الفرد، وفرض ضرائب عقارية تصاعدية على ما يتجاوز الحد.</li><li>حظر تأجير وبيع المساكن المضمونة؛ ويخالفون ذلك يفقدون أهلية الضمان وتُسترجع مساكنهم.</li><li>إنشاء نظام معلومات علني لمعاملات المساكن، لمنع العمليات الخفية والتلاعب بالأسعار.</li><li>فرض إدارة الأهلية ورقابة الأموال على مطوري العقارات، لمنع تعثر المشاريع والاحتيال.</li><li>إنشاء آليات الشكاوى وحل نزاعات الإسكان، لحماية الحقوق والمصالح المشروعة للساكنين.</li></ol><h2 id="سابعاً-المسؤولية-القانونية" tabindex="-1">سابعاً: المسؤولية القانونية <a class="header-anchor" href="#سابعاً-المسؤولية-القانونية" aria-label="Permalink to &quot;سابعاً: المسؤولية القانونية&quot;">​</a></h2><p>تتحمل الأفعال المخالفة لأحكام هذا القانون المسؤوليات التالية حسب جسامة الظروف:</p><ul><li>توزيع المساكن المضمونة بشكل مخالف للقواعد: الأمر بالتصحيح وتوقيع جزاءات على المسؤولين.</li><li>تأجير أو بيع المساكن المضمونة: فقدان أهلية الضمان واسترجاع المسكن ودفع غرامة.</li><li>المطورون الذين يخفضون جودة البناء: الأمر بإعادة العمل ودفع غرامة، وفي الحالات الجسيمة إلغاء الأهلية.</li><li>المضاربة على المساكن: فرض ضرائب مضاربة عالية وغرامات.</li><li>تأجير المباني المتهالكة المسبب للضرر للساكنين: تحمل مسؤولية التعويض، وفي الحالات الجسيمة تطبيق المسؤولية الجنائية.</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>قانون ضمان الإسكان</em> هو تجسيد فلسفة «لكل فرد طريق» في حضارة التكافل المرساة في مجال السكن. بإنشاء نظام ضمان إسكان متعدد الأنواع، واستخدام تقنية المبادئ القانونية المكانية لتوسيع المساحات السكنية، وتكييف احتياجات سكن الأعراق الأخرى، ومكافحة المضاربة على المساكن، يضمن حصول كل كائن على منزل آمن وملائم ومستقر، ويوفر ضمان السكن لتقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>39-住房与环境保障 (الإسكان وحماية البيئة)</li><li>13-空间法理调度体系详解 (الشرح المفصل لنظام تسيير المبادئ القانونية المكانية)</li><li>46-环境保护法 (قانون حماية البيئة)</li></ul>',29)])])}const u=a(i,[["render",e]]);export{g as __pageData,u as default};
